"""Audited concept inventory. Generates JSON, a full tree, glossary, and offline explorer."""
from pathlib import Path
import json, html, re, hashlib, datetime
R=Path(__file__).resolve().parent.parent
nodes=[]
def n(id,title,scope,definition,refs='',deps='',status='documented'):
    evidence=[]
    for ref in refs.split(';'):
        if ref.strip():
            if '|' in ref:
                src,loc=ref.strip().split('|',1);evidence.append({'source':src,'locator':loc})
            else: evidence[-1]['locator']+='; '+ref.strip()
    nodes.append(dict(id=id,title=title,scope=scope,status=status,definition=definition,evidence=evidence,dependencies=deps.split() if deps else []))
# Root and conceptual divisions. A dependency edge means explanatory dependency, not software import.
n('alphanist','AlphaNIST','core','A simulated assembly learning system combining heterogeneous tasks, a cached reset distribution adapted from OmniReset, adaptive success-based sampling, a shared geometry-conditioned actor and critic, a terminal assembly objective plus control penalties, and synchronous PPO. Each branch below separates its published mechanism from missing implementation particulars.','AlphaNIST|III–VI','task resets sampling reward learning network control physics evaluation context')
n('task','Task and mathematical problem','core','One policy is trained across twenty assembly-pair tasks; multiple-pair experiments train separate policies for each active-pair count. The simulator state, policy observation, objective, and reset distribution are different objects.','AlphaNIST|III-A; IV-C; V-D','nist mdp pomdp goal multi_task multi_pair')
n('resets','Which states can training start from','core','A bank stores assembly identity and simulator state. Reset coverage creates opportunities to learn contacts, grasps, transport, and completion without supplying the actions connecting those states. Sampling cannot create missing bank entries.','AlphaNIST|IV-B','omnireset reset_bank reset_prior reset_support gap_bank gap_adaptation')
n('sampling','Which available states get practiced','core','Each cached assembly–reset entry has a rolling success estimate. AlphaNIST weights intermediate success rates most highly and retains a positive floor for every entry. This changes the episode-start distribution over tasks as well as states.','AlphaNIST|Eq. 4; Algorithm 1','alpha_sampler success_history categorical beta sgs task_balance adaptive_objective gap_sampler gap_distributed_sampler')
n('reward','What behavior the objective favors','core','The positive task reward is sparse and binary; the complete reward includes dense control penalties. The success predicate and penalty scaling are essential to interpreting or reproducing the objective.','AlphaNIST|IV-C, Eqs. 5–6','success control_cost reward_scaling shaping discount termination gap_metric gap_cost gap_reward_timing')
n('learning','How experience changes the policy','core','PPO uses freshly collected policy rollouts to update an actor and value estimator. Value learning and function approximation can connect competence across nearby reset states, but do not guarantee a path between them.','AlphaNIST|Algorithm 1; IV-E; PPO|§§2–5','policy_gradient ppo value bellman gae optimization distributed credit gap_ppo')
n('network','What the policy observes and computes','core','Separate actor and critic parameters use the same illustrated architecture: point-cloud embedding concatenated with normalized proprioception/action input, followed by two SimBa-style residual blocks. The actor outputs eight action coordinates; the critic a scalar value.','AlphaNIST|Fig. 3; IV-D','point_cloud proprioception simba gaussian gap_encoder gap_observation gap_noise')
n('control','How a sampled action moves the robot','core','At 25 Hz, seven relative joint-position commands and a gripper command feed a hardware-matched simulated Panda. A low-level implicit impedance controller determines motion and contact response.','AlphaNIST|IV-D','robot joint_targets impedance limits system_id gripper gap_controller')
n('physics','What generates transitions','core','Isaac Lab hosts GPU-parallel physics environments. Contact representation, friction, integration, and solver settings determine the dynamics that RL optimizes against; hardware limits alone do not establish simulator fidelity.','AlphaNIST|II-A; IV-D; VI; Factory|III','isaaclab isaacgym factory rigid_body sdf friction solver timestep gap_simulator')
n('evaluation','What the reported evidence establishes','core','Results are task- and distribution-specific measurements in simulation. They establish strong performance within the tested setup, not unseen-geometry generalization, hardware reliability, or complete twenty-part sequences.','AlphaNIST|V–VI','metrics reset_evaluation scale compute multi_pair_result emergence ablation gap_eval gap_causality gap_hardware')
n('context','Related methods and conversation trails','comparison','These branches explain comparisons and borrowed concepts. They are not an assertion that every referenced method is implemented inside AlphaNIST.','AlphaNIST|II','related_assembly multitask_alternatives transfer alphago soccer conversation')
# Task and basic mathematical closure.
n('nist','NIST Assembly Task Board 1','core','The benchmark includes nuts and bolts, gears and shafts, rods/pegs and holes, and electrical connectors. AlphaNIST uses twenty movable-part/mating-geometry pairs. Physical NIST benchmarking also measures completion time, reliability, and test conditions; a simulated mixed-reset success rate is a different protocol.','AlphaNIST|I, Fig. 2; NIST-article|Task Board Design; Performance Metrics','assembly_geometry')
n('assembly_geometry','Insertion, meshing, threading and clearance','foundation','Insertion fits one body into a receptacle; gear meshing additionally aligns teeth; threading couples axial advancement with rotation. Clearance is the geometric gap permitting motion. Realistic rigid-body threading still has six-dimensional relative motion and can tilt, jam or cross-thread; it is not necessarily constrained to an ideal helix.','Factory|II-A4, Fig. 2; AlphaNIST|I','pose contact helix')
n('mdp','Markov decision process','foundation','The model contains states S, actions A, transition law p(s′|s,a), reward r, discount γ, horizon T and initial distribution ρ. Markov means the current state contains the information needed for next-state probabilities. In a finite-horizon problem the remaining time can be treated as part of state.','AlphaNIST|III-A, Eqs. 1–2; ConservativePolicyIteration|§2','state action probability return')
n('state','Simulator state versus configuration','foundation','A simulator state includes positions, orientations and velocities, robot joint state, and relevant physical or task variables. A pose alone is not the full dynamic state. A reset configuration specifies the state and context restored at episode start.','AlphaNIST|IV-B; SGS|§3.1','pose')
n('action','Policy action','foundation','An action is the control-interface command, not necessarily a physical torque. Here the eight-dimensional policy output describes seven arm-position increments and one gripper command; controller dynamics turn these into motion.','AlphaNIST|IV-D')
n('probability','Probability, expectation and empirical frequency','foundation','A probability lies in [0,1]. Expectation averages outcomes under a stated distribution. For Boolean outcomes y₁,…,yₙ, empirical success is Σy/n and estimates, but is not identical to, the current policy’s true success probability.','SGS|§3.2; AlphaNIST|III-A; IV-B')
n('return','Discounted finite-horizon return','foundation','Gₜ = Σₖ γᵏ rₜ₊ₖ until termination/horizon; the objective averages this return across starting states, transitions and sampled actions. With control costs, the objective is not just probability of successful assembly.','AlphaNIST|Eq. 2; GAE|§2','discount')
n('pomdp','Partial observation and history','foundation','The policy sees oₜ rather than the entire simulator state. Different hidden states may produce the same observation, so a memoryless policy need not be optimal. Stacked observations may reduce this aliasing without guaranteeing full observability. AlphaNIST states partial observations but leaves temporal packing unclear.','AlphaNIST|III-A, Fig. 3; AsymmetricActorCritic|III','gap_observation')
n('pose','Rigid pose and coordinate frames','foundation','A rigid pose is translation x∈R³ and rotation R∈SO(3), represented by a homogeneous transform T=[R x;0 1]. Object pose in the mating frame is T_mating⁻¹T_object. Quaternions represent rotation, with q and −q representing the same orientation; ordering conventions must be explicit.','AlphaNIST|IV-C; UWLab-code|docs/source/publications/omnireset/new_task.rst, Steps 1 and 4','rotation_distance')
n('rotation_distance','Translation and orientation error','foundation','Translation error has length units; an angular error can be computed from the relative rotation, for example acos(clamp((tr(R_goalᵀR)−1)/2,−1,1)). This is a generic definition, not AlphaNIST’s unpublished metric. Combining angle and length requires a convention or a geometry-based distance.','IndustReal|§IV-F; AlphaNIST|IV-C','gap_metric')
n('helix','Ideal threaded assembly path','foundation','For pitch h, ideal axial displacement and rotation obey z−z₀=hθ/(2π). A path generator can use this relation to propose near-goal poses; the physical simulation still solves contact and permits off-path states. AlphaNIST does not publish its per-part path functions.','SGS|Appendix A.2; Factory|Fig. 2','gap_adaptation')
n('goal','Goal configuration and assembly coordinate','core','For task e, Φₑ(α), α∈[0,1], parameterizes an assembly-relative configuration, with Φₑ(1) fully assembled. This supplies privileged geometric goal knowledge; it is neither a demonstrated action sequence nor the policy’s discrete task input.','AlphaNIST|IV-C','pose gap_metric gap_adaptation')
n('multi_task','Shared learning across assembly pairs','core','The same actor and value model serve different geometries. Task identity chooses simulator assets in the bank, while the actor receives geometry instead of an explicit task label. Shared parameters permit transfer, but the paper does not prove which representation or skill causes the observed gains.','AlphaNIST|III-A; IV-B; V-A','task_balance gap_causality')
n('multi_pair','Several pairs in one episode','core','Success requires every active pair to be assembled simultaneously. The agent may switch between unfinished pairs, with no prescribed order and no positive reward for completing an individual pair. A separate policy is trained for each active-pair count from one to ten.','AlphaNIST|IV-C; V-D; Table I','gap_multi_pair')
# Resets recursively into paper, code, and geometry.
n('omnireset','OmniReset reset generation','predecessor','OmniReset requests a target object, a sampler of goal states, and a workspace. It precomputes grasp poses and feasible offsets near the goal, generates four families of robot–object states, rejects invalid candidates, and caches accepted states for fast resets. AlphaNIST explicitly adapts the approach rather than specifying an identical implementation.','OmniReset|§§3.1–3.2','reset_inputs reaching near_object stable_grasp near_goal validation reset_cache omni_sampling')
n('reset_inputs','Human-supplied reset priors','predecessor','Object selection, goal transforms, workspace limits and robot/asset geometry constrain the distribution before learning. In current UWLab, metadata includes assembled offsets and success tolerances. No demonstrations does not mean absence of engineered information.','OmniReset|§3.1 Requirements 1–3; UWLab-code|docs/source/publications/omnireset/new_task.rst, Steps 1–5','goal pose')
n('reaching','Reaching resets','predecessor','OmniReset places the object at varied tabletop poses and the gripper around the workspace. SGS’s later Reaching strategy instead initially aligns the end effector with a grasp frame and randomizes aperture, allowing the object to fall. Identical family names do not establish identical distributions.','OmniReset|§3.2; SGS|Appendix A.2','ik')
n('near_object','Near-object resets','predecessor','The object rests on the table and the end effector starts near a precomputed grasp pose with perturbations and open/closed gripper states. This exposes contact initiation, including nonprehensile interaction. This is one of OmniReset’s four families; SGS reports three families.','OmniReset|§3.2; SGS|Appendix A.2','grasp_sampling')
n('stable_grasp','Stable-grasp resets','predecessor','OmniReset places the object in air and the gripper at a feasible grasp pose. This exposes transport without requiring pickup first. A cached pose is only as physically credible as its grasp-validation and friction models.','OmniReset|§3.2','grasp_sampling validation friction')
n('near_goal','Near-goal and partial-assembly resets','predecessor','OmniReset begins at a known goal, applies small random forces, and collects feasible offsets; the gripper is then placed in contact nearby. SGS instead explicitly describes task-dependent assembly-path profiles. Neither description establishes the exact construction used for every AlphaNIST pair.','OmniReset|§3.2; SGS|Appendix A.2; UWLab-code|partial_assemblies_cfg.py, PartialAssembliesEventCfg','partial_assembly goal grasp_sampling gap_adaptation')
n('partial_assembly','Offline partial-assembly generation','predecessor','Current UWLab starts from assembled offsets, sets both bodies’ friction to zero, applies random force and torque components in [−0.005,0.005], and logs feasible relative poses. This is a public generator for useful states, not evidence that AlphaNIST used these numbers. The cited IndustReal paper explains sampling curricula but does not by itself specify this exact force-displacement recipe.','UWLab-code|partial_assemblies_cfg.py, lines 83–142; OmniReset|§3.2; IndustReal|§IV-G','industreal validation')
n('grasp_sampling','Grasp pose generation','predecessor','OmniReset reports 1,000 feasible grasps and cites ORBIT. The current UWLab implementation samples object surface points, favors high/upward-facing surfaces, casts inward rays to opposing points within gripper aperture, then samples orientation and standoff. Closing and perturbing the grasp plus collision checks validate candidates. ORBIT alone does not provide this full recipe.','OmniReset|§3.2; ORBIT|Fig. 8 and agent interfaces; UWLab-code|events.py::_sample_antipodal_grasps; grasp_sampling_cfg.py','antipodal validation ik grasp_limits')
n('antipodal','Opposing-contact grasp candidates','foundation','Opposing surface contacts suggest a parallel-jaw grasp. A true frictional force-closure claim additionally depends on normals and friction cones. UWLab’s ray/opposing-point heuristic and simulator tests should not be described as an exhaustive mathematical force-closure proof.','UWLab-code|events.py::_sample_antipodal_grasps; grasp_sampling_cfg.py','friction')
n('ik','Inverse kinematics','foundation','Forward kinematics maps joint angles to a gripper pose. Inverse kinematics seeks joint angles realizing a desired pose, subject to reachability and joint limits. Multiple solutions or no solution may exist; feasibility and collision rejection matter when converting grasp poses to arm resets.','SGS|Appendix A.2; UWLab-code|reset_states_cfg.py; events.py::reset_end_effector_from_grasp_dataset','pose validation')
n('grasp_limits','Limits of the public grasp sampler','predecessor','UWLab documents failures for adversarial/unusual shapes and possible task-specific tuning of sampling and minimum collision distance at millimeter precision. Its current release also documents some Isaac Lab 3 training regressions. These are implementation limitations, not unpublished proprietary concepts.','UWLab-code|docs/source/publications/omnireset/new_task.rst, Known Limitations; rl_training.rst, known regressions')
n('validation','Reset physical feasibility','predecessor','Reject candidates with unacceptable collisions, let the simulator settle, and check grasp/object stability. Contact is allowed and necessary; invalid interpenetration is different from intended contact. Approximate collision checks can still miss problematic configurations.','OmniReset|§3.2 Practical Implementation; UWLab-code|collision_analyzer.py; grasp_sampling_cfg.py','contact sdf')
n('reset_cache','Cached states versus replayed trajectories','foundation','A reset cache stores states to initialize new simulator rollouts. It does not provide a recorded action trajectory or replay old state-action transitions into PPO. Caching validated states reduces reset-time cost and avoids repeated online feasibility work.','OmniReset|§3.2; AlphaNIST|Algorithm 1','on_policy')
n('omni_sampling','Uniformity over states versus reset families','predecessor','Uniform sampling over a union of finite datasets weights each family in proportion to its number of entries. Current UWLab first selects a family using configured probabilities, then samples a state uniformly within it. Equal family probability equals uniform-over-all-entries only for equal dataset sizes.','OmniReset|§3.2 Practical Implementation; UWLab-code|events.py::MultiResetManager','categorical')
n('reset_bank','Assembly-indexed reset bank','core','D_reset={(eᵢ,s̄ᵢ)} stores the part/mating-geometry identity with robot, board and object state. Sampling an entry jointly changes task and starting condition. Bank multiplicities therefore affect the training prior even before adaptive weighting.','AlphaNIST|Eq. 3, IV-B','reset_cache task_balance gap_bank')
n('reset_prior','Initial-state distribution is an inductive bias','inference','Providing near-success and grasped starts makes useful experience much more likely than unstructured starts. The human knowledge lies in the support and weighting of initial states, as well as geometry and goals. This does not tell the policy the connecting actions.','OmniReset|§§3.1–3.2; AlphaNIST|IV-B','reset_support credit',status='derived')
n('reset_support','Coverage is finite and approximate','inference','A finite bank is not all valid states. If a useful start is absent, SGS cannot select it; rollouts may still reach states outside the bank. Coverage and learned generalization determine whether competence transfers to a desired deployment start distribution.','OmniReset|§3.2; SGS|Appendix B.3','reset_evaluation',status='derived')
# Sampling lineage and exact distinctions.
n('alpha_sampler','AlphaNIST sampling equation','core','qᵢ=[εq+√(p̂ᵢ(1−p̂ᵢ))]/Σⱼ[εq+√(p̂ⱼ(1−p̂ⱼ))]. The kernel is symmetric and maximized at 0.5; without the floor, p̂=0 and p̂=1 have zero weight. All p̂ᵢ initialize to zero in Algorithm 1, so a common positive floor initially produces a uniform bank distribution.','AlphaNIST|Eq. 4; Algorithm 1','bernoulli beta categorical success_history gap_sampler')
n('success_history','Rolling empirical success','core','AlphaNIST uses the latest L Boolean outcomes per entry. It is a moving history from changing policies, not an exact success probability or calibrated posterior. Window length trades noise against staleness; rarely visited entries can have stale estimates. SGS reports H=100, which is not a published AlphaNIST L.','AlphaNIST|IV-B; SGS|§3.2; Appendix B.2','probability gap_sampler')
n('bernoulli','Bernoulli variance and learning heuristic','foundation','For success Y∈{0,1} with probability p, Var(Y)=p(1−p); its standard deviation is √(p(1−p)). Both peak at p=0.5. This measures variability of success, not guaranteed expected policy improvement: irreducibly stochastic tasks can also have p near one half.','SFL|§4; AlphaNIST|Eq. 4','probability')
n('categorical','Normalized categorical sampling','foundation','For nonnegative weights wᵢ with positive sum, choose entry i with probability wᵢ/Σwⱼ. The normalizer couples entries: adding or duplicating a bank entry changes probabilities. This is sampling a discrete index, not sampling a continuous success rate.','AlphaNIST|Eq. 4; SGS|Eq. 2','probability')
n('beta','Beta-shaped kernel is not a Bayesian posterior','foundation','The Beta(a,b) density is proportional to p^(a−1)(1−p)^(b−1) on [0,1]. AlphaNIST’s unfloored kernel has a=b=1.5. It evaluates that shape at observed success rates to weight discrete entries; it does not draw p from a fitted posterior, and is not Thompson sampling.','AlphaNIST|Eq. 4; SGS|§3.2','categorical bernoulli')
n('sgs','General SGS sampler','predecessor','SGS uses wᵢ=(pᵢ+ε)^(κt)(1−pᵢ+ε)^(κ(1−t)), logit log(wᵢ+ε), then softmax with temperature T. Appendix B.2 additionally floors w and T. Manipulation defaults are t=.5, κ=1, ε=10⁻⁴, T=2, H=100 and N=32,768 configurations.','SGS|§3.2, Eqs. 1–2; Appendix B.2','temperature sampler_difference sfl reverse_curriculum plr')
n('temperature','Softmax temperature changes the kernel','foundation','softmax(log(w+ε)/T) is proportional to (w+ε)^(1/T). Larger T flattens differences. Ignoring epsilon, t=.5 and κ=1 yield [p(1−p)]^(1/(2T)); SGS’s T=2 therefore gives a fourth-root shape, not AlphaNIST’s square-root equation.','SGS|Eqs. 1–2; Appendix B.2; AlphaNIST|Eq. 4','beta',status='derived')
n('sampler_difference','Published AlphaNIST and SGS formulas differ','inference','The two papers share the success-frontier principle, but their printed effective weights differ in epsilon placement, temperature, and flooring. Treat AlphaNIST Eq. 4 as its declared rule. Whether the unreleased code implements it exactly cannot be resolved from SGS defaults.','AlphaNIST|Eq. 4; SGS|§3.2; Appendix B.2','gap_sampler',status='derived')
n('sfl','Sampling for Learnability lineage','comparison','SFL scores levels using p(1−p), evaluates a pool of levels and retains high-scoring ones. SGS explicitly acknowledges the same moderate-success principle, while using rolling histories and a smooth beta-shaped sampler over a fixed configuration set. Neither success variability nor regret is identical to actual future learning gain.','SFL|§4, Algorithm 1; SGS|§2','bernoulli plr')
n('plr','Prioritized Level Replay','comparison','PLR preferentially revisits levels using learning-potential scores such as value-prediction error and a staleness component. It replays environment levels, not necessarily old transitions. SGS instead directly weights empirical success. These methods can disagree when value error and success variability differ.','PLR|§3, Algorithms 1–2; SGS|§2','value')
n('reverse_curriculum','Reverse curriculum generation','comparison','Florensa et al. start near a supplied goal, generate nearby starts with random actions, and expand using starts with intermediate success. OmniReset instead proposes broad fixed reset coverage; SGS adapts sampling weights over a fixed pool. These are distinct mechanisms despite similar intuition.','ReverseCurriculum|§4, Algorithm 1; OmniReset|§2','goal bernoulli')
n('task_balance','Task frequency induced by reset weights','inference','P(e)=Σᵢ:eᵢ=e qᵢ. Thus adaptive reset sampling also reweights assembly tasks. Equal numbers of states per task do not ensure equal task sampling once their success rates differ. Equal episode allocation also need not mean equal transition allocation when episode lengths vary.','AlphaNIST|Eqs. 3–4; Algorithm 1','categorical',status='derived')
n('adaptive_objective','Training distribution moves with the policy','inference','ρ is introduced as an initial distribution, while Algorithm 1 updates it from recent policy outcomes. PPO is therefore optimized on a changing mixture. The paper does not describe importance correction back to a fixed uniform task objective; evaluation explicitly uses a different, frozen distribution.','AlphaNIST|III-A; IV-B; V','on_policy reset_evaluation',status='derived')
# Rewards.
n('success','Terminal full-assembly reward','core','For a single pair, success is 1[d_asmᵉ(sₜ₊₁)<0.001 m]; it is issued once and terminates the episode. Multi-pair success requires all active assemblies at once. The threshold is explicit; the complete distance computation and symmetry handling are not.','AlphaNIST|Eq. 5; IV-C','goal gap_metric')
n('control_cost','Dense action, speed and torque cost','core','rₜ=rₜ^succ−c(‖aₜ‖²+‖q̇ₜ‖²+‖τₜ‖²), with fixed c≥0 across tasks. It discourages effort without directly rewarding assembly progress. Unlike OmniReset’s formula, the printed AlphaNIST equation has a torque penalty but no action-difference penalty.','AlphaNIST|Eq. 6; OmniReset|Appendix A.1','norm energy reward_scaling gap_cost')
n('norm','Squared Euclidean norm','foundation','For vector x, ‖x‖₂²=Σⱼxⱼ². Components with twice the magnitude contribute four times the penalty. The result depends on units, preprocessing and which coordinates are included; equal coefficients alone do not imply equal physical influence.','AlphaNIST|Eq. 6')
n('energy','Torque penalty is not measured energy','foundation','Mechanical power is τᵀq̇ and mechanical work integrates power over time. Squared torque is an effort-related surrogate. Neither squared action nor squared torque alone is a measurement of electrical energy consumption.','SGS|Appendix A.3.1, mechanical power; AlphaNIST|Eq. 6')
n('reward_scaling','Term weighting versus numerical normalization','foundation','Changing relative reward weights changes the optimization objective. Rescaling a whole fixed objective by a positive constant preserves mathematical rankings, but can change neural optimization unless optimizer and auxiliary terms scale compatibly. Observation normalization, advantage normalization and PopArt target normalization are different operations.','RewardShaping|§§2–3; PopArtMultitask|§2; DeepMindSoccer|Methods; Table S3','norm popart gap_cost')
n('shaping','Progress shaping and policy invariance','foundation','A distance-to-goal bonus can favor partial behavior or alter optimal policies. Potential shaping F(s,s′)=γΨ(s′)−Ψ(s) preserves policy rankings under the theorem’s assumptions and appropriate terminal potentials, because its discounted sum telescopes. AlphaNIST’s tested reach/alignment bonuses are not stated to have this form.','RewardShaping|Theorem 1; AlphaNIST|Eq. 7','potential_terminal dense_ablation')
n('potential_terminal','Why shaping boundary conditions matter','foundation','Σₜγᵗ[γΨ(sₜ₊₁)−Ψ(sₜ)]=−Ψ(s₀)+γᴴΨ(s_H). If the final potential depends on the terminal outcome, a finite-horizon return can change ranking. Setting appropriate terminal potential or including time in the potential is necessary; arbitrary distance bonuses do not automatically qualify.','RewardShaping|Theorem 1 and proof','discount',status='derived')
n('dense_ablation','The tested dense reward is one choice','core','AlphaNIST adds reach and orientation-alignment rewards with c₂=c₃=.01 and observes worse joint training than its sparse-task objective. This does not prove all dense shaping is inferior. Its claim that these coefficients match OmniReset conflicts with OmniReset v3 Appendix A.1, which lists .1 for reach and distance.','AlphaNIST|V, Eq. 7; OmniReset|Appendix A.1','gap_reward_comparison')
n('discount','Discount and the incentive to finish early','foundation','For 0<γ<1, a success reward received sooner has larger discounted value. With γ=1 and zero control cost, equally successful trajectories need not favor earlier completion. Cost accumulation can favor shorter/lower-effort paths, but there is no general shortest-path guarantee. AlphaNIST’s numerical γ is unpublished.','AlphaNIST|Eq. 2; GAE|§2','gap_ppo')
n('termination','Success, timeout and unsafe termination','core','Episodes stop at success, horizon, or arm velocity/torque violation. The text requires success without simultaneous safety failure. Correct value targets distinguish terminal outcomes from rollout cuts and any bootstrapable time limits; exact masks and precedence are not published.','AlphaNIST|IV-C; V; PPO|§5','gap_reward_timing limits')
# Optimization and foundations.
n('value','Actor, critic and advantage','foundation','The actor defines πθ(a|o). The critic estimates expected future return Vϕ(o); Q(s,a) conditions on a chosen action. Advantage A=Q−V compares that action with average behavior. With costs and discount, V is not simply assembly success probability.','GAE|§2; AlphaNIST|Fig. 3','return')
n('bellman','Bootstrapping and Bellman recursion','foundation','Vπ(s)=E[r+γVπ(s′)] with the future term removed at a true terminal state. Learning a useful value near completion can influence estimates farther away through sampled transitions. A neural approximation can generalize across states, but approximation error can also propagate.','GAE|§§2–3; ConservativePolicyIteration|§2','value termination')
n('policy_gradient','Likelihood-ratio policy gradient','foundation','Policy-gradient updates weight ∇θ log πθ(aₜ|oₜ) by estimated advantage. Positive advantage favors the sampled action and negative advantage disfavors it. The environment need not be differentiable; sampled rewards and transitions train the networks.','PPO|§2.1; GAE|§2','value gaussian optimization')
n('ppo','Proximal Policy Optimization','core','The clipped objective averages min(ratio·Â, clip(ratio,1−ε,1+ε)·Â), with ratio=πθ(a|o)/πold(a|o). Clipping limits incentives for some large probability changes; it is not a hard guarantee on every policy change. AlphaNIST names standard PPO but omits many settings.','PPO|§3 Eq. 7; AlphaNIST|IV-E','on_policy importance gae trpo entropy gap_ppo')
n('importance','Action-probability ratio','foundation','The new/old probability ratio compares policies on actions sampled by the old policy. This action correction is distinct from correcting a changed reset distribution. PPO’s clipped surrogate is not an exact unbiased importance estimator after clipping.','PPO|§§2–3','probability')
n('on_policy','Fresh rollouts and bounded data reuse','foundation','PPO collects trajectories with a current policy, then performs several optimization passes on that batch. It is called on-policy despite this short reuse window; it does not ordinarily maintain an unrestricted old-transition replay buffer as off-policy algorithms do.','PPO|§5, Algorithm 1; AlphaNIST|Algorithm 1')
n('gae','Generalized Advantage Estimation','foundation','Using TD residual δₜ=rₜ+γV(sₜ₊₁)−V(sₜ), GAE computes Âₜ=Σₗ(γλ)ˡδₜ₊ₗ with termination masks and truncation handling. λ trades bias and variance. PPO’s source gives this estimator; AlphaNIST does not explicitly publish its advantage-estimator configuration.','GAE|§3; PPO|§5','bellman gap_ppo')
n('trpo','TRPO and conservative policy iteration','lineage','TRPO seeks policy improvement with a constrained average KL change; PPO replaces the expensive constrained update with simpler surrogate objectives. Conservative policy iteration supplies earlier improvement and restart-distribution analysis. Their guarantees do not automatically prove convergence of AlphaNIST’s neural PPO setup.','TRPO|§§3–4; PPO|§2.2; ConservativePolicyIteration|§§3–4','kl')
n('entropy','Exploration entropy','foundation','Entropy measures distributional spread: H(π)=−E log π(a|o). An entropy bonus can discourage premature collapse of a stochastic policy. AlphaNIST’s Gaussian output does not establish the entropy coefficient, variance schedule or use of gSDE.','PPO|Eq. 9; AlphaNIST|Fig. 3','gaussian gap_noise gap_ppo')
n('optimization','Minibatches, gradients and Adam','foundation','Backpropagation differentiates a neural loss; minibatch optimization averages sample gradients. Adam tracks first and second gradient moments, bias-corrects them and scales updates. Adam is documented in the PPO lineage and public predecessor config, but AlphaNIST’s exact optimizer settings are not disclosed.','Adam|Algorithm 1; PPO|§5; UWLab-code|agents/rsl_rl_cfg.py','gap_ppo')
n('distributed','Synchronous distributed PPO','core','AlphaNIST averages actor and critic gradients across GPUs before each optimizer step. It reports 4K environments/GPU in multi-GPU runs, 32 rollout steps/environment, five epochs and four minibatches. Model architecture and settings are said to stay fixed as environment count scales.','AlphaNIST|IV-E','batch_scale gap_distributed_sampler')
n('batch_scale','Parallelism changes the optimization batch','inference','With N environments and 32 steps, each iteration collects 32N transitions. Holding iterations fixed while increasing N increases data, batch size and compute together. Four minibatches mean larger minibatches at larger N. This does not isolate a pure hardware-parallelism effect.','AlphaNIST|IV-E; V','compute',status='derived')
n('credit','How skills can connect across reset states','inference','Near-goal success supplies useful value/advantage targets; experience beginning farther away can learn actions that reach high-value states. Shared function approximation can transfer across reset neighborhoods and tasks. No stored graph, stage label, or demonstrated connecting motion is required; connectivity and successful learning are not guaranteed.','OmniReset|§§3.2–3.3; GAE|§3','bellman reset_support',status='derived')
# Networks.
n('point_cloud','Geometry conditioning through point clouds','core','The actor observes surface points for the movable part, mating geometry and robot, rather than a discrete task token. This makes task-relevant geometry available. It does not establish camera-based perception, occlusion handling, or generalization to unseen shapes; the paper’s results use simulation.','AlphaNIST|III-A; IV-D; VI','encoder gap_encoder gap_observation')
n('encoder','Point-cloud encoder specification','core','Figure 3 shows a two-layer ELU encoder with widths 256 and 128 from 3×n_pts input. It does not state n_pts, point sampling, coordinate frame, aggregation/pooling, segmentation, or how point order is treated. Calling it PointNet would add an unverified architectural claim.','AlphaNIST|Fig. 3','elu gap_encoder')
n('proprioception','Robot measurements and previous action','core','Figure 3 lists pose 7, twist 6, joints 9, action 8, but labels the input as 150 dimensional. The listed quantities sum to 30; five stacked frames would explain 150, but the paper does not explicitly confirm that packing, frame convention or history spacing.','AlphaNIST|Fig. 3','pose gap_observation')
n('simba','SimBa-style residual architecture','core','SimBa normalizes observations with running statistics, uses pre-layer-normalized residual MLP blocks, and layer-normalizes the final representation. AlphaNIST illustrates two blocks of width 256 with 1024-wide expansions, using Swish, whereas original SimBa describes ReLU. Preserve that distinction.','SimBa|§4, Eqs. 3–7; AlphaNIST|Fig. 3','running_norm layer_norm residual swish')
n('running_norm','Running observation normalization','foundation','Track per-feature mean μ and variance σ² across samples, then use (x−μ)/√(σ²+ε). This changes input scale; it is not reward normalization. AlphaNIST shows RN on the 150-dimensional input branch, but does not publish statistics synchronization or update/freeze rules.','SimBa|§4 Eqs. 3–4; AlphaNIST|Fig. 3','gap_observation')
n('layer_norm','Layer normalization','foundation','Normalize a sample’s hidden features using their mean and variance, optionally with learned affine scale and shift. Unlike batch normalization, the statistics are within that sample’s layer rather than across examples. This stabilizes representation magnitude; it does not normalize physical reward units.','LayerNorm|§3; SimBa|§4')
n('residual','Residual connection','foundation','A block computes x+F(x), preserving an identity path while learning a correction. AlphaNIST’s two blocks use layer normalization, linear expansion, nonlinear activation and linear contraction. Residual structure can aid optimization without guaranteeing a simpler or more general policy.','ResNet|§3.2; SimBa|Eq. 6; AlphaNIST|Fig. 3')
n('swish','Swish activation','foundation','Swish is f(x)=x·sigmoid(βx); β=1 is often called SiLU. AlphaNIST labels its activation Swish, but does not specify β. Original SimBa uses ReLU, so the architecture is an adaptation.','Swish|§3; AlphaNIST|Fig. 3','gap_network_details')
n('elu','ELU activation','foundation','ELU(x)=x for x>0 and α(exp(x)−1) otherwise. It provides a smooth negative branch. AlphaNIST labels its point encoder ELU without publishing the α setting or precise point aggregation.','ELU|§2; AlphaNIST|Fig. 3','gap_network_details')
n('gaussian','Gaussian action distribution','core','The actor samples actions from a Gaussian distribution described by a mean and covariance (often diagonal in robotics). AlphaNIST confirms a Gaussian eight-dimensional output but not its variance parameterization, clipping/squashing, initial scale, or joint/gripper postprocessing.','AlphaNIST|Fig. 3; PPO|§6','gap_noise')
n('kl','Kullback–Leibler divergence','foundation','D_KL(P‖Q)=E_P[log(P/Q)] quantifies a directional distribution mismatch. It is nonnegative but generally asymmetric. It appears in trust-region constraints and distribution distillation; the direction and normalization matter.','TRPO|§3; DextrAH-RGB|§III-C')
# Controllers and physical simulation.
n('robot','Panda embodiment','core','A seven-DoF arm plus a parallel-jaw gripper is simulated. Nine joint coordinates can include seven arm joints and two finger coordinates, while the policy controls only one gripper coordinate. Exact observation interpretation still requires the unpublished packing.','AlphaNIST|IV-D, Fig. 3','gripper')
n('joint_targets','Relative joint-position targets','core','q_target=q_current+Δq at each 25 Hz policy step. This differs from accumulating increments on the previous target and from commanding Cartesian displacement. Action scaling and clipping determine the numerical Δq; they are not published.','AlphaNIST|IV-D','impedance gap_controller')
n('impedance','Joint impedance and implicit actuation','foundation','A schematic controller uses torque Kp(q_target−q)−Kd q̇ plus any compensation terms. Stiffness trades tracking against compliant contact; damping suppresses velocity. An implicit simulator drive solves effects within its integration/constraint step, so it is not automatically identical to a real actuator or an explicit PD calculation.','AlphaNIST|IV-D; libfranka-control|setJointImpedance documentation; IsaacLab|actuator modeling','system_id timestep gap_controller')
n('limits','Joint-speed and torque limits','core','AlphaNIST specifies 2.175 rad/s for arm joints 1–4, 2.61 rad/s for 5–7, and 87 Nm / 12 Nm torque limits respectively. Exceeding limits ends the episode. Whether action/actuator clipping is additionally used, and how simultaneous success is handled, remains an implementation question.','AlphaNIST|IV-C–D','gap_controller gap_reward_timing')
n('system_id','System identification and drivetrain effects','foundation','System identification fits model parameters from real measurements. Armature adds effective inertia; friction resists motion; latency delays commands. AlphaNIST says parameters are identified and hardware matched but does not publish the complete parameter vector, fitting dataset or validation residuals.','AlphaNIST|IV-D; OmniReset|Appendix A.3.2','gap_controller')
n('gripper','Driven and coupled finger','core','One finger is driven and one mechanically coupled passive finger follows. Finger kinematics, contact pad friction and gripper command mapping affect what grasps are physically stable. The robot’s two finger coordinates do not imply two independent policy actions.','AlphaNIST|IV-D','friction gap_controller')
n('isaaclab','Isaac Lab environment framework','core','Isaac Lab integrates assets, scene simulation, sensors, actions, observations, rewards, resets, randomization and learning interfaces. It is the reported AlphaNIST framework; a framework citation does not identify every version or default actually used in the experiment.','IsaacLab|framework overview and environment abstractions; AlphaNIST|IV-D','isaacgym gap_simulator')
n('isaacgym','GPU-native parallel simulation lineage','lineage','Isaac Gym keeps simulation state and learning tensors on the GPU to reduce CPU transfer overhead and run many environments in parallel. Isaac Lab is its successor framework. Parallel environments provide experience throughput, not independent physical hardware evidence.','IsaacGym|§3; IsaacLab|Introduction','distributed')
n('factory','Factory contact simulation','lineage','Factory combines signed distance fields for collision geometry, reduced contact patches and a Gauss–Seidel solver to make detailed assembly simulation tractable. AlphaNIST cites this simulation lineage; its exact contact asset and solver configuration remain unreported.','Factory|§III; AlphaNIST|II-A','sdf contact_reduction solver')
n('rigid_body','Rigid-body dynamics','foundation','A schematic robot equation is M(q)q̈+C(q,q̇)+g(q)+f(q̇)=τ+J(q)ᵀf_contact. M is inertia, C velocity-dependent terms, g gravity, f friction, J the contact Jacobian. A rigid approximation omits deformation and requires contact constraints and numerical integration.','OperationalSpaceControl|dynamic modeling; Factory|II-A','contact friction solver')
n('contact','Nonpenetration and contact constraints','foundation','Contact modeling prevents excessive overlap and determines forces/impulses when bodies meet. In an ideal complementarity view, nonnegative normal force acts at zero gap, while positive gap has no normal force. Finite time steps and tolerances make the numerical model approximate.','Factory|II-A; III','sdf solver')
n('sdf','Signed distance field','foundation','An SDF maps a point to signed distance from a surface; its sign convention distinguishes inside from outside and its gradient supplies a local normal. A voxel grid approximates it. Resolution and sampling affect small-feature accuracy, so a mesh image alone does not establish collision fidelity.','Factory|II-A1; III-A; IndustReal|IV-E–F')
n('contact_reduction','Contact patch reduction','foundation','Many nearby contacts with similar normals can be grouped and reduced while trying to preserve their combined wrench. Fewer constraints reduce memory and solver cost. The procedure is an approximation whose settings can affect force and torque predictions.','Factory|III-B–C')
n('friction','Friction model and combine rule','foundation','Coulomb friction bounds tangential force by μ times normal force. Material coefficients and combine modes determine the effective contact μ. SGS reports that OmniReset’s pad μ=100 encouraged implausible grasps and uses μ=2; AlphaNIST does not publish its pad friction, so neither value can be imported.','OmniReset|Appendix A.3.4; SGS|Appendix C.2','gap_simulator')
n('solver','Iterative contact solver','foundation','Gauss–Seidel updates constraints sequentially using latest estimates; Jacobi uses previous-iteration values and parallelizes more easily. Contact reduction can make Gauss–Seidel competitive at scale. Iteration count, tolerances and substeps affect stability and penetration.','Factory|II-A3; III-B','timestep gap_simulator')
n('timestep','Physics step versus policy step','foundation','A policy step can hold one action across several physics steps (decimation). AlphaNIST gives 25 Hz policy control, not its full physics timing. SGS gives 200 Hz physics and eight steps per Franka action; those are SGS settings, not confirmed AlphaNIST values.','AlphaNIST|IV-D; SGS|Appendix A.2','gap_simulator')
# Evaluation and nearby literature.
n('metrics','Training success versus evaluation success','core','The 98.2% number is shared-policy training success at 64K environments. The 97.4% versus 84.3% sampler comparison is frozen-bank evaluation at 256K. These measure different experiments and should not be mixed into one headline hardware accuracy claim.','AlphaNIST|V-A–B, Figs. 5–7','reset_evaluation')
n('reset_evaluation','Start distribution defines the test','core','Scaling evaluation uses stochastic actions, a common frozen mixed-reset bank, uniform sampling within each task, 32 trials/task/seed and five evaluation seeds. Success rates cover all reset configurations. A partially assembled start is easier than a full pickup-to-insertion trial; the mixed result does not state a table-only success rate.','AlphaNIST|V; Fig. 7','gap_eval')
n('scale','Reported sampling and scale ablation','core','At 256K environments sparse-task success is 97.4% with beta sampling and 84.3% with uniform sampling; dense-reward counterparts are 77.4% and 34.3%. These support a gain in the tested setup, while data volume and batch size also grow with scale.','AlphaNIST|V-B','batch_scale ablation')
n('compute','Interaction budget and GPU-hours','core','The shared policy uses 410 GPU-hours versus 16.1K aggregate GPU-hours for twenty sparse-reward specialists, approximately 39.3×. Comparisons match per-run interaction budgets, not aggregate data for all specialists. GPU-hours are device-hours, not wall-clock hours or a hardware-independent efficiency measure.','AlphaNIST|V-A','gap_compute')
n('multi_pair_result','One-to-ten pair results','core','Table I reports 99,97,95,93,92,90,89,87,86,84 percent for one through ten active pairs, with policies trained and evaluated at the same count and 15 seconds allowed per pair. Twenty simultaneous active pairs remain future work.','AlphaNIST|Table I; V-D; VI','multi_pair gap_multi_pair')
n('emergence','Observed dexterity and planning-like behavior','core','Figures and videos show regrasping, geometry-assisted reorientation, nut tapping/threading and switching between partially completed tasks. This supports the observation of coordinated behavior. It does not identify an internal symbolic planner, prove optimal planning, or show general performance on arbitrary assemblies.','AlphaNIST|V-C–D, Figs. 8–9','gap_causality')
n('ablation','What an ablation identifies','foundation','Changing one component while holding others fixed estimates its effect in that tested setup. Results do not establish necessity in all settings. AlphaNIST’s beta-versus-uniform comparison uses the same bank, so it tests allocation conditional on coverage, not whether broad reset coverage itself is necessary.','AlphaNIST|IV-B; V; SGS|Appendix B.3','dense_ablation')
n('related_assembly','Alternative assembly pipelines','comparison','Prior work supplies useful contrasts: Factory uses subpolicies; IndustReal adds simulator/reward/curriculum and control techniques; AutoMate uses assembly-by-disassembly and imitation; Refinery improves specialist initialization; ARCH uses an explicit hierarchy. None should be silently inserted into AlphaNIST.','AlphaNIST|II-C','industreal automate refinery arch')
n('industreal','IndustReal','comparison','IndustReal addresses interpenetration artifacts in training, uses an SDF-based dense alignment reward, samples starts with a curriculum, and applies a policy-level action integrator for transfer. Its sampling-based curriculum retains easier starts while expanding difficulty. This is explanatory reset/control lineage, not AlphaNIST’s reward.','IndustReal|§IV-E–G; §V; Appendix on PLAI','sdf shaping')
n('automate','AutoMate assembly by disassembly','comparison','AutoMate generates disassembly trajectories, reverses them into assembly paths, trains specialist RL policies with an imitation objective, and distills/fine-tunes a generalist. These are trajectory-guided policies; OmniReset’s unordered reset states do not supply the same action/path supervision.','AutoMate|§§IV–VI','imitation')
n('refinery','Refinery active initialization','comparison','Refinery uses Bayesian-optimization-guided initial-state selection to fine-tune pretrained assembly specialists, then models favorable deployment initializations using a Gaussian mixture. It requires a pretrained-policy pipeline and does not establish AlphaNIST’s sampler or reset geometry.','Refinery|Method, Fig. 1')
n('arch','ARCH explicit hierarchical assembly','comparison','ARCH uses a high-level learned planner to select and parameterize lower-level skills combining RL and model-based control. AlphaNIST’s multi-pair policy is described without this explicit hierarchy. Its planning-like behavior should not be confused with ARCH’s architecture.','ARCH|Abstract; Method')
n('multitask_alternatives','Multi-task optimization alternatives','comparison','Task sharing can introduce conflicting gradients or unequal target scales. PCGrad and PopArt address those issues explicitly. AlphaNIST reports standard shared PPO without task-specific value heads or gradient projection; this does not prove those issues never occur.','AlphaNIST|II-B','pcgrad popart unitary')
n('pcgrad','PCGrad gradient projection','comparison','For conflicting gradients gᵢ·gⱼ<0, project gᵢ away from gⱼ via gᵢ←gᵢ−(gᵢ·gⱼ/‖gⱼ‖²)gⱼ. This explicitly modifies multi-task updates. AlphaNIST states that it does not use gradient projection.','PCGrad|§3, Algorithm 1; AlphaNIST|II-B')
n('popart','PopArt target normalization','comparison','PopArt maintains target mean/scale and adjusts the output layer when those statistics change so unnormalized predictions are preserved. For f=σ(Wh+b)+μ, use W′=σW/σ′ and b′=(σb+μ−μ′)/σ′. Multi-task PopArt uses task-specific statistics/heads; this is distinct from changing physical reward terms.','PopArt|§2; PopArtMultitask|§2; AlphaNIST|II-B')
n('unitary','Ordinary scalarized multi-task training','comparison','Kurin et al. show that summing task losses with standard regularization/stabilization can match specialized optimizers on tested benchmarks. This supports considering simple baselines; it does not guarantee that AlphaNIST’s task mixture is balanced or optimal.','UnitaryScalarization|Abstract; experimental conclusions')
n('transfer','Predecessor sim-to-real pipeline','predecessor','OmniReset and SGS train simulator experts and distill perception-based students, with system identification and randomization for transfer. AlphaNIST reports simulation only and leaves sensor-derived deployment to future work. Predecessor hardware results are not AlphaNIST hardware validation.','OmniReset|§5; Appendix A.3; SGS|Appendix C; AlphaNIST|VI','asymmetric gsde distillation randomization transfer_curriculum transfer_limits')
n('asymmetric','Asymmetric actor-critic','predecessor','The critic can use privileged simulator information unavailable to the deployed actor. OmniReset uses this separation. AlphaNIST illustrates actor and critic with the same inputs and separate parameters; inheriting OmniReset’s privileged critic or five-frame actor setting would be unsupported.','AsymmetricActorCritic|III; OmniReset|§3.3, Appendix A.3.9; AlphaNIST|Fig. 3','pomdp')
n('gsde','Generalized state-dependent exploration','predecessor','gSDE samples a noise matrix periodically and multiplies it by policy features: a=μ(s)+W_noise z(s). Holding the matrix between resampling steps creates correlated exploration; state-dependent variance alone does not. OmniReset says it uses gSDE; AlphaNIST does not establish that choice.','gSDE|§§2.2–3; OmniReset|§3.3','gaussian')
n('distillation','Teacher-to-student policy distillation','predecessor','A privileged expert labels actions/distributions for a student observing images. OmniReset describes 80K trajectories, an ImageNet-pretrained ResNet-18 encoder, a 4-layer 512-unit MLP, KL action matching and auxiliary object-pose reconstruction. It cites DextrAH-RGB, whose own student learning uses online DAgger; these collection procedures differ.','OmniReset|Appendix A.3.11; DextrAH-RGB|§III-C','kl imitation resnet_student dagger')
n('imitation','Behavior cloning and state-distribution shift','foundation','Behavior cloning fits expert actions on collected observations. If errors push the learner into unfamiliar states, errors can compound. This is a different supervision source from PPO learning only from environment rewards; distillation after RL does not mean the original RL used human demonstrations.','DextrAH-RGB|§III-C; AutoMate|generalist learning','dagger')
n('dagger','DAgger data aggregation','foundation','Roll out the learner, ask the expert for actions at states the learner visits, add those labels to the dataset, and retrain. This targets the learner-induced observation distribution. DextrAH-RGB uses an online variant; OmniReset discusses image-based DAgger as future work.','DAgger|§3, Algorithm 3.1; DextrAH-RGB|§III-C; OmniReset|Appendix A.3.11')
n('resnet_student','ResNet visual encoder','foundation','Residual image networks learn convolutional features with skip connections. OmniReset’s student uses pretrained ResNet-18 features and end-to-end fine-tuning; this is separate from AlphaNIST’s surface-point encoder and residual MLP.','ResNet|§3; OmniReset|Appendix A.3.11','residual')
n('randomization','Domain randomization','foundation','Randomize simulator dynamics and/or visual factors to expose a policy or student to a distribution of conditions. It aims to reduce sensitivity to mismatch but cannot guarantee coverage of real-world physics or perception. AlphaNIST’s full randomization distribution is not reported.','DomainRandomization|§3; OmniReset|Appendix A.3.7; SGS|Appendix C.2','gap_simulator')
n('transfer_curriculum','Curricula in predecessor transfer experiments','predecessor','OmniReset A.3.9 transitions from simplified dynamics to system-identified dynamics after training. SGS B.4 says its main manipulation experiments use a success-triggered gravity curriculum and reports a one-seed no-curriculum ablation. These facts limit blanket claims that the entire predecessor pipelines have no curricula; they do not prove AlphaNIST used one.','OmniReset|Appendix A.3.9; SGS|Appendix B.4','gap_adaptation')
n('transfer_limits','Friction, distillation and seed-selection caveats','predecessor','OmniReset selects seeds by action-noise robustness and reports a gap between state experts and vision students. SGS identifies unrealistic high-friction grasps and modifies pad friction. These reveal concrete sources of simulation-to-hardware mismatch, but not AlphaNIST’s unreported configuration.','OmniReset|Appendix A.3.10–11; SGS|Appendix C.2–3','friction gap_hardware')
n('alphago','AlphaGo Zero is motivation, not the algorithm','comparison','AlphaGo Zero combines self-play, a policy/value network and Monte Carlo tree search to create training targets from game outcomes. AlphaNIST invokes sparse-objective inspiration but describes PPO in a continuous robot environment, with no reported tree search or adversarial self-play.','AlphaGoZero|self-play learning; AlphaNIST|I; II-C','ppo')
n('soccer','DeepMind soccer and reward weights','conversation','The user’s intended paper is Learning Agile Soccer Skills for a Bipedal Robot with Deep Reinforcement Learning, not the wheeled-robot paper initially suggested in the chat. Its Table S3 gives per-stage weights, e.g. scoring 1000, velocity-to-ball .05, forward velocity .1, knee-torque penalty .01 for the full 1v1 agent. These demonstrate relative scaling but do not supply AlphaNIST c.','DeepMindSoccer|Methods; Supplementary Table S3','reward_scaling')
n('conversation','Audit of the shared conversation','conversation','The chat correctly separates reset generation from success-based selection and notes missing reward scaling. Its near-goal story describes OmniReset, with an explicit caveat about AlphaNIST adaptation. Treat the chat as a trail of questions, not primary evidence; the archived transcript preserves the user’s soccer-paper correction.','Conversation|user/assistant messages; AlphaNIST|IV-B–C; OmniReset|§3.2','soccer sampler_difference reset_prior')
# Additional branches exposed by auditing the predecessor explanations.
n('procurl','ProCuRL and the limits of learnability theory','lineage','ProCuRL selects starting states by PoS_current × (PoS_optimal − PoS_current). If optimal success is one, this becomes p(1−p). Its justifications consider restricted settings including independent tasks and simple learners. They do not prove that middle-success resets maximize improvement for a shared neural robot policy.','ProCuRL|§§3.1–3.2; SFL|§4','bernoulli')
n('pace','PACE calibration pipeline','predecessor','OmniReset explicitly follows PACE for actuator identification. PACE replays measured joint-target trajectories in many simulated environments and minimizes mean squared simulated-versus-real joint-position error. It fits effective joint dynamics with evolutionary search. Its discussion of identifiability explains why a fitted parameter vector need not uniquely reveal microscopic actuator physics. This does not establish that AlphaNIST used the same fitting procedure.','PACE|§2, Eqs. 3–7; OmniReset|Appendix A.3.2','cmaes identifiability')
n('cmaes','Covariance matrix adaptation evolution strategy','foundation','CMA-ES samples candidate parameter vectors from a multivariate Gaussian, ranks their objective values, and updates its mean, step size and covariance using successful search directions. It requires objective evaluations rather than derivatives through the simulator. Its search covariance is unrelated to an RL policy’s action covariance.','CMAES|§§1–3; PACE|Eq. 4')
n('identifiability','Parameter identifiability','foundation','A parameter is identifiable from a measurement protocol only when different values produce distinguishable observations under that protocol. PACE gives an example: co-scaling inertia, damping and PD gains can preserve joint trajectories. Accurate trajectory fitting alone therefore does not establish a unique physical model or contact accuracy.','PACE|§2, Eqs. 6–7','gap_controller')
n('bayesopt','Bayesian optimization and acquisition functions','foundation','Fit a probabilistic surrogate to measured objective values, then choose a new evaluation using an acquisition score balancing predicted value and uncertainty. Refinery uses Gaussian-process estimates and studies upper confidence bound, probability of improvement and expected improvement. These propose initialization conditions for policy fine-tuning; they are not SGS’s per-entry success weights.','Refinery|§IV-A, Algorithm 1','gaussian_process')
n('gaussian_process','Gaussian-process surrogate','foundation','A Gaussian process defines a joint Gaussian distribution over function values at any finite collection of inputs. A covariance kernel specifies their prior relationship; conditioning on observations yields a predictive mean and uncertainty. Refinery uses these to model success across initializations.','Refinery|§IV-A')
n('gmm','Gaussian mixture model','foundation','A mixture density is a weighted sum of Gaussian component densities with nonnegative weights summing to one. Refinery fits it to successful plug initializations, samples candidate initializations, and chooses a high-density candidate at deployment. Mixture density is not itself a calibrated probability of policy success.','Refinery|§IV-B, Algorithm 2')
n('osc','Operational-space control','predecessor','Operational-space control expresses desired motion and forces in task coordinates such as end-effector pose, and uses robot dynamics to map them to joint torques. OmniReset’s UR7e transfer controller uses Cartesian targets. AlphaNIST instead reports relative joint-position commands; copying the predecessor’s Cartesian action scale would change its interface.','OperationalSpaceControl|operational-space formulation; OmniReset|Appendix A.3.5–6; AlphaNIST|IV-D','jacobian')
n('jacobian','Kinematic Jacobian and wrench mapping','foundation','The Jacobian J(q) maps joint velocity to local end-effector or contact velocity: v=J(q)q̇. By virtual work, a task-space wrench F maps to generalized joint force JᵀF. Near singular configurations some Cartesian motions become difficult or impossible to produce with bounded joint motion.','OperationalSpaceControl|kinematics and dynamic formulation','pose')
n('mcts','Monte Carlo tree search','comparison','AlphaGo Zero searches a tree of possible moves, guided by network move priors and value estimates. Simulations select branches using visit/value statistics, expand and evaluate leaves, and back up values. Root visit counts define improved move-selection targets. No corresponding tree-search module is reported for AlphaNIST.','AlphaGoZero|Methods: Search algorithm','selfplay')
n('selfplay','Self-play learning','comparison','In AlphaGo Zero the current system plays both sides of the game. Search-generated move distributions and final game outcomes train the policy/value network, which then guides future search. A robot learning against passive assembly geometry is not this adversarial training loop.','AlphaGoZero|Methods: Self-play reinforcement learning')
for parent,children in {'sfl':'procurl','system_id':'pace','refinery':'bayesopt gmm','transfer':'osc','rigid_body':'jacobian','alphago':'mcts'}.items():
    next(x for x in nodes if x['id']==parent)['dependencies'].extend(children.split())
# Undocumented leaves: every question has a specific reason and closure requirement.
gaps=[
('gap_bank','Exact AlphaNIST reset-bank contents','M, per-task/per-family counts, generation seeds, pose/velocity distributions, saved fields, rejection thresholds and the bank files are absent. A descriptive family list cannot reconstruct the distribution.','AlphaNIST|IV-B; OmniReset|§3.2','Publish the bank or deterministic generator, assets, configurations and seed list.'),
('gap_adaptation','Exact adaptation from OmniReset and SGS','The paper does not say which grasp generator, near-goal force/path method, workspace bounds, family mixing, gravity curriculum or randomization settings were carried over. Predecessors disagree on several of these choices.','AlphaNIST|IV-B; OmniReset|§3.2; SGS|Appendices A.2 and B.4','Release AlphaNIST reset and environment configs; distinguish inherited from changed components.'),
('gap_sampler','Sampler numerical and bookkeeping settings','AlphaNIST leaves L and εq numerical values unspecified and does not explain short histories, repeated concurrent entry outcomes, update ordering, or any hidden temperature/flooring. SGS defaults do not exactly reproduce AlphaNIST Eq. 4.','AlphaNIST|IV-B, Algorithm 1; SGS|§3.2, Appendix B.2','Release the sampler implementation and a tiny deterministic sampling test.'),
('gap_distributed_sampler','Global formula versus GPU-local banks','Eq. 4 normalizes over the entire bank, but IV-E says each GPU samples a local bank from local rolling estimates. Bank replication/sharding, cross-rank statistics and task balance are not specified. These choices can change the effective global distribution.','AlphaNIST|IV-B and IV-E','Publish rank-local bank mapping, update synchronization and normalization behavior.'),
('gap_metric','Exact success distance and symmetry handling','d_asm is called a distance between relative poses and compared with 0.001 m, but its formula, keypoints, angle-to-length conversion, rotational symmetries and task-dependent equivalences are missing. For threads, depth, turn count and orientation acceptance cannot be reconstructed.','AlphaNIST|IV-C, Eq. 5','Publish the success predicate, goal transforms, units, symmetry groups and per-part examples.'),
('gap_cost','Control-cost coefficient and units','The value of c, per-term normalization, action scaling, arm/finger inclusion, torque source and clamp rules are not reported. Mixing action, rad/s and Nm squared without this information leaves the numerical objective underdetermined.','AlphaNIST|Eq. 6; Fig. 3; IV-D','Release the reward code/config and logged term magnitudes before and after scaling.'),
('gap_reward_timing','Reward timing and termination masks','Eq. 5 uses sₜ₊₁ while Eq. 6 lists t-indexed commands/speeds/torques. Per-physics-step versus policy-step aggregation, dt scaling, simultaneous-success precedence, reset masks and timeout bootstrap handling are unspecified.','AlphaNIST|IV-C; V','Publish the environment step order, reward manager behavior and terminal/bootstrap flags.'),
('gap_ppo','Full PPO and optimization configuration','Numerical discount γ, GAE λ (or alternate estimator), clip ratio, value/entropy weights, optimizer parameters, learning-rate schedule, gradient clipping, reward/advantage normalization, initialization and timeout handling are absent. Standard PPO is a family of implementations.','AlphaNIST|IV-E; PPO|§§3–6','Release complete trainer config, library versions and checkpoint metadata.'),
('gap_encoder','Point-cloud construction and encoder aggregation','n_pts, sampling method, coordinate frame, visibility/occlusion, segmentation, noise, ordering/pooling and per-part allocation are unspecified. The two-layer figure does not uniquely define a permutation-invariant point encoder.','AlphaNIST|Fig. 3; IV-D','Publish observation generation and encoder forward pass, with tensor-shape examples.'),
('gap_observation','Proprioception packing and history','Listed feature counts sum to 30 while Fig. 3 says 150. Five-frame stacking is plausible but unconfirmed. Pose/twist frames, joint coordinate meanings, history timing, normalization updates and distributed statistics are not fully specified.','AlphaNIST|Fig. 3; III-A; IV-D','Publish observation schema and normalization/history implementation.'),
('gap_noise','Gaussian exploration and action processing','Covariance parameterization, initialization, variance sharing, temporal correlation, squashing/clipping and gripper mapping are missing. Gaussian output alone does not establish independent diagonal noise or gSDE. Evaluation is explicitly stochastic, but its exact distribution and postprocessing are not specified.','AlphaNIST|Fig. 3; IV-D; V','Publish action-distribution and postprocessing code for training and stochastic evaluation.'),
('gap_network_details','Exact neural layer settings','ELU alpha, Swish beta, normalization epsilon/affine settings, parameter initialization and whether all encoder parameters are separate for actor/critic are not exhaustively enumerated. Figure 3 says separate parameters but does not provide executable architecture.','AlphaNIST|Fig. 3; SimBa|§4','Publish network constructors and serialized model architecture.'),
('gap_controller','Controller gains and identified robot model','Exact stiffness/damping profiles, armature, joint friction, gripper mechanics, action scales, saturation, torque measurement and libfranka version are not given. Manufacturer docs establish interfaces, not the experiment’s chosen parameter vector.','AlphaNIST|IV-D; libfranka-control|setJointImpedance','Publish robot asset/config, identified parameters, controller settings and identification data.'),
('gap_simulator','Physics versions, assets and numerical settings','AlphaNIST does not enumerate simulator/library commits, collision asset checksums, SDF resolution, contact offsets, friction/restitution, timestep/decimation, solver iteration count or all randomizations. PhysX/Newton background citations do not uniquely identify the experiment’s backend/configuration.','AlphaNIST|II-A; IV-D; VI; Factory|III','Release environment lockfile, asset manifests and full physics configuration.'),
('gap_multi_pair','Multi-pair observation and reset construction','The rule for sampling active task subsets, maintaining fixed point counts, representing inactive/completed parts, combining partial-assembly starts, collision-valid multi-part resets, and evaluation trial counts is not fully described. Table I alone does not establish full-from-table ten-part success.','AlphaNIST|IV-C; V-D; Table I','Publish active-set sampling, scene/observation generation, reset banks and per-family evaluation.'),
('gap_eval','Evaluation independence and uncertainty','Scaling evaluation defines a frozen mixed bank, but its separation from training banks, per-family sizes and seed-generation details are not stated. Fig. 7 uses five evaluation seeds, which must not be re-labeled five independent training runs. Table I lacks comparable uncertainty/trial details.','AlphaNIST|V; Figs. 5–7; Table I','Publish train/test bank overlap checks, per-training-seed checkpoints, evaluation seeds and raw outcomes.'),
('gap_causality','Why transfer and planning-like behavior emerge','The paper proposes an explanation for sparse-objective transfer but does not isolate the causal representation/skill mechanism or prove planning optimality. This is an open empirical explanation, not evidence of proprietary technology.','AlphaNIST|V-A and V-C–D','Requires targeted ablations/representation tests or additional published evidence; existing descriptions cannot settle it.'),
('gap_hardware','AlphaNIST hardware and unseen-condition performance','No AlphaNIST hardware transfer result or full twenty-active-pair result is reported. Predecessor hardware success cannot fill this gap. Robustness to real perception, latency and contact mismatch remains unestablished.','AlphaNIST|VI','Requires new evaluations with sensor-derived observations and specified physical/held-out conditions.'),
('gap_compute','Full compute accounting','GPU model, training-vs-reset-generation cost accounting, preprocessing overhead and wall-clock breakdown are not sufficiently specified to turn GPU-hours into reproducible runtime/cost estimates. Matching iterations also changes total interactions with environment count.','AlphaNIST|IV-E; V-A','Publish hardware, timing logs, preprocessing costs and interaction totals.'),
('gap_reward_comparison','Cross-paper reward-coefficient discrepancy','AlphaNIST says its .01 reach/alignment coefficients match OmniReset. OmniReset v3 Appendix A.1 and inspected UWLab main list .1 reach/distance-related weights. Terms may also differ in scaling. The exact experimental correspondence remains unresolved.','AlphaNIST|V, Eq. 7; OmniReset|Appendix A.1; UWLab-code|rl_state_cfg.py, reward config','Publish version-specific ablation configs and clarify whether effective weights or term scales differ.'),
]
for id,title,definition,refs,closure in gaps:
    n(id,title,'boundary',definition,refs,status='undocumented');nodes[-1]['needed_to_resolve']=closure

# Serialization and all text derivatives generated from one inventory.
lookup={x['id']:x for x in nodes}
assert len(lookup)==len(nodes)
for x in nodes:
    assert all(d in lookup for d in x['dependencies']),x['id']
    assert x['definition'] and x['evidence'],x['id']
edges=[{'from':x['id'],'to':d,'relation':('missing_detail' if lookup[d]['status']=='undocumented' else 'explanatory_dependency')} for x in nodes for d in x['dependencies']]
seen=set();stack=set()
def walk(i):
    if i in stack:raise ValueError('Cycle '+i)
    if i in seen:return
    stack.add(i)
    for d in lookup[i]['dependencies']:walk(d)
    stack.remove(i);seen.add(i)
walk('alphanist');assert len(seen)==len(nodes),set(lookup)-seen
G={'title':'AlphaNIST concept graph','as_of':'2026-10-14','root':'alphanist','scope':'Operational concepts required to explain the reported AlphaNIST method; predecessor mechanisms, relevant comparisons and foundational definitions. Not a transitive crawl of every cited paper in all of robotics.','status_definitions':{'documented':'Meaning is stated with primary evidence; this does not establish that AlphaNIST adopted every predecessor detail.','derived':'Explicit reasoning from the cited equations or source descriptions, not a reported experimental result.','undocumented':'Missing implementation, unresolved source conflict or empirical result not established in the inspected public evidence. Not a claim of proprietary status.'},'nodes':nodes,'edges':edges}
(R/'concept-graph.json').write_text(json.dumps(G,ensure_ascii=False,indent=2)+'\n')
manifest=json.loads((R/'sources/papers.json').read_text())+json.loads((R/'sources/support.json').read_text())
sources={x['id']:x for x in manifest if x['status']=='downloaded'}
sources['Conversation']={'id':'Conversation','path':'sources/shared-conversation.json','url':'https://chatgpt.com/share/6acf821c-d6f4-83e9-bf97-c5bad96593d9'}
sources['UWLab-code']={'id':'UWLab-code','path':'sources/code/UWLab-main/docs/source/publications/omnireset/index.rst','url':'https://github.com/UW-Lab/UWLab/tree/2b40afb9693d46bc1b1a91c7ba95e03c04daa60d'}
def refs_md(x):
    return '; '.join('['+r['source']+']('+sources[r['source']]['path']+') '+r['locator'] for r in x['evidence'])
for x in nodes:
    for r in x['evidence']:assert r['source'] in sources, r
(R/'sources/catalog.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2)+'\n')
lines=['# AlphaNIST concept definitions','',G['scope'],'','Statuses describe evidence, not certainty of successful reproduction. Undocumented leaves name what would resolve them.','']
for x in nodes:
    lines += [f"<a id=\"{x['id']}\"></a>",f"## {x['title']}",'',f"**{x['status']} · {x['scope']}**",'',x['definition'],'', '**Evidence:** '+refs_md(x),'']
    if x.get('needed_to_resolve'):lines+=['**Needed to resolve:** '+x['needed_to_resolve'],'']
    if x['dependencies']:lines+=['**Follow:** '+', '.join(f"[{lookup[d]['title']}](#{d})" for d in x['dependencies']), '']
(R/'CONCEPTS.md').write_text('\n'.join(lines))
lines=['# AlphaNIST full concept tree','','This is a spanning tree of the graph. Repeated nodes use cross references; follow them to the full definition and all dependencies. Every branch is reachable from AlphaNIST. See [the interactive explorer](concept-graph.html) for search and parent links.','']
expanded=set()
def tree(i,depth=0):
    x=lookup[i];repeat=i in expanded
    lines.append('  '*depth+'- '+f"[{x['title']}](CONCEPTS.md#{i})"+' — '+x['status']+(' (shared reference)' if repeat else ''))
    if repeat:return
    expanded.add(i)
    for d in x['dependencies']:tree(d,depth+1)
tree('alphanist')
(R/'CONCEPT-TREE.md').write_text('\n'.join(lines)+'\n')
lines=['# AlphaNIST unresolved evidence boundaries','','These are the remaining questions after tracing the papers, appendices and public predecessor code. No item is labeled proprietary: publication or code absence alone does not establish proprietary ownership. Empirical limitations require experiments, not merely another definition.','']
for j,(id,*_) in enumerate(gaps,1):
    x=lookup[id];lines += [f"## {j}. {x['title']}",'',x['definition'],'','**Checked:** '+refs_md(x),'','**Closure requirement:** '+x['needed_to_resolve'],'']
# relative paths for a document stored in project root, deliberately keep there.
(R/'AMBIGUITIES.md').write_text('\n'.join(lines))
print(len(nodes),'nodes;',len(edges),'edges;',len(gaps),'undocumented boundaries;',len(sources),'sources')
template=(R/'research/explorer-template.html').read_text()
def safe_json(data):return json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
(R/'concept-graph.html').write_text(template.replace('__GRAPH_DATA__',safe_json(G)).replace('__SOURCE_DATA__',safe_json(sources)))
